__NUXT_JSONP__("/th/faq-covid19", (function(a){return {data:[{details:{slug:"th",pageTitle:"คำถามที่พบบ่อย - COVID 19 | Mentor Language Institute",pageDescription:a,title:"คำถามที่พบบ่อย - COVID 19",types:[{title:a,lists:[{question:"แนวทางปัจจุบันสำหรับการเดินทางไปสหรัฐอเมริกาคืออะไร?",answer:["1. พลเมืองที่ไม่ใช่ชาวอเมริกันทุกคนที่บินไปยังสหรัฐอเมริกาจะต้องได้รับการฉีดวัคซีนอย่างครบถ้วน ดังนี้: (การฉีดวัคซีนสองโดส: ไฟเซอร์ โมเดอร์นา) หรือ (การฉีดวัคซีนครั้งเดียว: จอห์นสัน แอนด์ จอห์นสัน) \u003Cbr \u002F\u003E นอกจากนี้ ก่อนขึ้นเครื่องไปยังสหรัฐอเมริกา คุณต้องแสดงผลการทดสอบ COVID-19 เป็นลบ ซึ่งใช้เวลาไม่เกิน 1 วันก่อนเดินทาง \u003Cbr \u002F\u003E โปรดปฏิบัติตามคำแนะนำของสายการบินแต่ละแห่งที่เกี่ยวข้องกับการทดสอบ PCR และการส่งใบรับรองเชิงลบ [CDC] เที่ยวอเมริกา  \u003Ca href='https:\u002F\u002Fwww.cdc.gov\u002Fcoronavirus\u002F2019-ncov\u002Ftravelers\u002Fnoncitizens-US-air-travel.html' target='_blank'\u003E https:\u002F\u002Fwww.cdc.gov\u002Fcoronavirus\u002F2019-ncov\u002Ftravelers\u002Fnoncitizens-US-air-travel.html \u003C\u002Fa\u003E","Los Angeles County กำหนดให้ผู้เดินทางทุกคนกรอก \"แบบฟอร์มการเดินทาง\" ก่อนเดินทาง แบบฟอร์ม: \u003Ca href='https:\u002F\u002Ftravel.lacity.org\u002F' target='_blank'\u003E https:\u002F\u002Ftravel.lacity.org\u002F \u003C\u002Fa\u003E"]},{question:"นโยบายของ MLI เกี่ยวกับการเข้าเรียนแบบตัวต่อตัวคืออะไร?",answer:["MLI ปฏิบัติตามแนวทางของรัฐแคลิฟอร์เนียและประเทศลอสแองเจลิสเพื่อให้ทุกคนปลอดภัยและป้องกันการแพร่กระจายของ COVID-19 คุณต้องปฏิบัติตามกฎระเบียบต่อไปนี้:","1. นักเรียนทุกคนที่เข้าร่วมโปรแกรมแบบตัวต่อตัวต้องได้รับการฉีดวัคซีนอย่างครบถ้วน ดังนี้ (การฉีดวัคซีนสองโดส: ไฟเซอร์ โมเดอร์นา) หรือ (การฉีดวัคซีนครั้งเดียว: จอห์นสัน แอนด์ จอห์นสัน) \u003Cbr \u002F\u003E 2. ไม่ต้องกักกัน \u003Cbr \u002F\u003E 3. คุณต้องทำการทดสอบ PCR ภายใน 1 วันก่อนเที่ยวบินของคุณและส่งผลลบที่เขียนเป็นภาษาอังกฤษไปยัง MLI ทางอีเมล"]},{question:"ฉันควรทำอย่างไรก่อนเดินทางมาถึงสหรัฐอเมริกา\u002Fออกจากประเทศบ้านเกิดของฉัน?",answer:["คุณต้องได้รับการฉีดวัคซีนครบถ้วนและทำการทดสอบ PCR ไม่เกิน 1 วันก่อนเดินทาง มิเช่นนั้น คุณจะไม่สามารถขึ้นเครื่องได้ โปรดส่งผล PCR ของคุณเป็นภาษาอังกฤษทางอีเมลไปยังวิทยาเขตของคุณ"]},{question:"ข้อยกเว้น COVID สำหรับกฎ 5 เดือนครอบคลุมระยะเวลาใด?",answer:["ไม่มีกฎ 5 เดือนในช่วงการระบาดใหญ่นี้ ตราบใดที่คุณมี I-20 ที่ถูกต้อง คุณก็จะสามารถมาที่สหรัฐอเมริกาได้"]},{question:"ฉันควรทำอย่างไรหากโปรแกรมของฉันออนไลน์อยู่ แต่ฉันต้องการไปสหรัฐอเมริกาตอนนี้",answer:["เราจะอนุญาตให้คุณเข้าเรียนในชั้นเรียนออนไลน์ที่คุณเลือกได้โดยไม่มีค่าใช้จ่ายเพิ่มเติม แต่คุณจะต้องเรียนในชั้นเรียนแบบตัวต่อตัวด้วยเพื่อรักษาสถานะของคุณ"]},{question:"ฉันต้องกรอกแบบฟอร์มใด ๆ ก่อนเดินทางมาถึงหรือไม่?",answer:["ใช่ คุณจะต้องกรอก \"แบบฟอร์มนักเดินทาง\" ก่อนเข้าสู่ลอสแองเจลิส \u003Ca href='https:\u002F\u002Ftravel.lacity.org\u002F' target='_blank'\u003Ehttps:\u002F\u002Ftravel.lacity.org\u002F \u003C\u002Fa\u003E"]},{question:"หากฉันมีวีซ่านักเรียน ฉันสามารถมาที่สหรัฐอเมริกาโดยไม่มีปัญหาได้หรือไม่",answer:["หากคุณมีวีซ่านักเรียน (ที่ยังไม่หมดอายุ) คุณสามารถสมัคร I-20 ใหม่และเริ่มโปรแกรมใหม่ได้ โปรดตรวจสอบข้อจำกัดการเดินทางสำหรับนักเดินทางต่างประเทศ"]},{question:"ฉันสามารถมาที่สหรัฐอเมริกาและเข้าร่วมโปรแกรมออนไลน์เท่านั้นได้หรือไม่",answer:["ไม่ ตามข้อบังคับของ SEVP นักเรียนต่างชาติที่เข้าเรียนใน I-20 เบื้องต้นไม่สามารถเข้าเรียนออนไลน์ได้ 100%"]},{question:"จะเกิดอะไรขึ้นหากมีการล็อกดาวน์อีกครั้งในแอลเอ",answer:["เราจะปฏิบัติตามคำแนะนำของ CDC และเปลี่ยนไปใช้โปรแกรมออนไลน์หากจำเป็น"]}]},{title:"สถานการณ์ในโรงเรียน",lists:[{question:"MLI มีคลาสออนไลน์หรือคลาสตัวต่อตัวหรือไม่?",answer:["MLI เสนอชั้นเรียนทั้งแบบออนไลน์และแบบตัวต่อตัว นักเรียนที่มาสหรัฐอเมริกาก่อนวันที่ 3\u002F09\u002F20 สามารถเข้าเรียนออนไลน์หรือเรียนแบบตัวต่อตัว ในทางกลับกัน นักเรียนที่มาสหรัฐอเมริกาด้วยวีซ่านักเรียนหลังวันที่ 3\u002F09\u002F20 จะต้องเข้าเรียนด้วยตนเอง ดังนั้น MLI จึงเสนอชั้นเรียนแบบตัวต่อตัวเพื่อเติมเต็มข้อกำหนดด้านการย้ายถิ่นฐานสำหรับนักเรียน F1"]},{question:"คุณเสนอโปรแกรม ESL ด้วยตนเองหรือไม่?",answer:["ใช่ เรามีชั้นเรียน ESL แบบตัวต่อตัวที่วิทยาเขตทั้งสองแห่ง นอกจากนี้ยังมีชั้นเรียน TOEFL และการสนทนาด้วยตนเอง"]},{question:"กิจกรรมของโรงเรียน MLI ถูกยกเลิกหรือไม่?",answer:["เนื่องจากสถานการณ์โควิด-19 กิจกรรมของโรงเรียนส่วนใหญ่จึงถูกระงับ เพื่อความปลอดภัยของนักเรียน คณาจารย์ และเจ้าหน้าที่"]},{question:"MLI มีผู้ป่วยยืนยันติดเชื้อโควิด-19 หรือไม่?",answer:["ใช่ มีกรณีที่ได้รับการยืนยันจากเซิร์ฟเวอร์ของ COVID-19 ที่ MLI เมื่อนักเรียนรู้สึกไม่สบาย เราต้องการให้พวกเขาทำการทดสอบ PCR และส่งผลการทดสอบเชิงลบก่อนที่จะกลับไปที่มหาวิทยาลัย หากนักเรียนมีผลตรวจเป็นบวกสำหรับ COVID-19 เรากำหนดให้นักเรียนทุกคนในชั้นเรียนทำการทดสอบ PCR และส่งผลการทดสอบเชิงลบให้ MLI ก่อนกลับไปที่มหาวิทยาลัย เฉพาะนักเรียนที่ส่งการทดสอบ PCR เชิงลบเท่านั้นที่ได้รับอนุญาตให้เข้าร่วมในชั้นเรียนของมหาวิทยาลัยอีกครั้ง"]},{question:"เมื่อไรโรงเรียนจะกลับมามีชั้นเรียนแบบตัวต่อตัวโดยสมบูรณ์?",answer:["เราเสนอ ESL, TOEFL และโปรแกรมสนทนาด้วยตนเอง โปรแกรม TOEFL ภาคค่ำและการสนทนาขั้นสูงภาคค่ำเปิดสอนทางออนไลน์"]},{question:"ฉันจะรับหนังสือเรียนได้อย่างไร",answer:["คุณสามารถซื้อหนังสือเรียนจากมหาวิทยาลัยของคุณ หรือเราจะส่งหนังสือเรียนไปให้คุณทางไปรษณีย์ หากคุณเลือกให้ส่งหนังสือเรียนทางไปรษณีย์ คุณจะถูกเรียกเก็บค่าธรรมเนียมการจัดส่ง"]},{question:"โรงเรียนของคุณมีการจัดการชั้นเรียนแบบตัวต่อตัวในช่วงการระบาดใหญ่อย่างไร?",answer:["ทุกคนในวิทยาเขตจะต้องส่งหลักฐานการฉีดวัคซีน มีการวัดอุณหภูมิทุกวันเมื่อมาถึงโรงเรียนและสวมหน้ากากตลอดเวลา"]},{question:"คุณเสนอโปรแกรมอะไร",answer:["โปรแกรม ESL, TOEFL, Conversation Intermediate และ Conversation Advanced มีให้ด้วยตนเอง นักศึกษาจะถูกสัมภาษณ์โดยเจ้าหน้าที่วิชาการของเราและจัดให้อยู่ในระดับที่เหมาะสม โปรแกรม TOEFL ภาคค่ำและการสนทนาขั้นสูงภาคค่ำเปิดสอนทางออนไลน์"]},{question:"ฉันสามารถเช็คอินในหอพักนักเรียนในวันที่ฉันมาถึงสหรัฐอเมริกาได้หรือไม่",answer:["ได้ นักเรียนสามารถเช็คอินในที่พักของนักเรียนได้ในวันที่เดินทางมาถึง หากนักเรียนแสดงหลักฐานการฉีดวัคซีนครบถ้วนและผล PCR เชิงลบที่นำมา 3 วันก่อนออกเดินทาง"]},{question:"ฉันจะลาพักร้อนในขณะที่เรียนโปรแกรมออนไลน์ได้อย่างไร",answer:["กรุณากรอกแบบฟอร์มออนไลน์นี้และแจ้งให้พนักงานต้อนรับส่วนหน้าทราบ \u003Ca href='https:\u002F\u002Fdocs.google.com\u002Fforms\u002Fd\u002Fe\u002F1FAIpQLSeA8-ApGetD5IEzxtnCeYKz4FlJ4VBpplImzw306AEGLkJk0w\u002Fviewform' target='_blank'\u003Ehttps:\u002F\u002Fdocs.google.com\u002Fforms\u002Fd\u002Fe\u002F1FAIpQLSeA8-ApGetD5IEzxtnCeYKz4FlJ4VBpplImzw306AEGLkJk0w\u002Fviewform \u003C\u002Fa\u003E"]}]},{title:"การรับสมัคร",lists:[{question:"ฉันสามารถเลื่อนการรับเข้าเรียนด้วยเหตุผลที่เกี่ยวข้องกับ COVID-19 ได้หรือไม่?",answer:["ได้ คุณสามารถเปลี่ยนวันที่เริ่มต้นโปรแกรมของคุณได้ โปรดแจ้งให้เราทราบเมื่อคุณต้องการเริ่มโปรแกรมของคุณตามวันที่เริ่มต้นที่ระบุไว้ในปฏิทินโรงเรียนของเรา หากคุณเป็นนักเรียน F1 (วีซ่านักเรียน) เราจะออก I-20 ของคุณใหม่พร้อมวันที่เริ่มต้นโปรแกรมใหม่ และส่ง I-20 ที่ลงนามแบบดิจิทัลให้คุณ เพื่อให้คุณสามารถพิมพ์ออกมาและนำติดตัวไปด้วยเมื่อคุณเข้าสู่ เรา"]},{question:"ฉันจะได้รับสำเนา I-20 ของฉันได้อย่างไร",answer:["ในช่วงการระบาดใหญ่ หน่วยงานของรัฐทุกแห่งจะยอมรับสำเนาดิจิทัลของ I-20 ของคุณ อย่างไรก็ตาม หากคุณต้องการ I-20 เดิม เราสามารถจัดส่งให้คุณได้ ในกรณีนี้ คุณจะถูกเรียกเก็บค่าธรรมเนียมการจัดส่ง"]},{question:"ฉันต้องเสียค่าธรรมเนียมหรือไม่หากฉันเลื่อนวันเริ่มเรียน",answer:["ไม่ หากคุณเป็นนักเรียน F1 (ผู้ถือวีซ่านักเรียน) เราจะส่งอีเมล I-20 ใหม่ให้คุณพร้อมระบุวันที่เริ่มต้นโปรแกรมใหม่"]},{question:"หลักฐานการฉีดวัคซีนและผล PCR ต้องเป็นต้นฉบับหรือไม่?",answer:["ไม่ ไม่จำเป็นต้องใช้ต้นฉบับ ยอมรับสำเนาหลักฐานการฉีดวัคซีนและผลการทดสอบ PCR"]},{question:"จะมีการคิดค่าปรับสำหรับการเลื่อนวันย้ายเข้าที่อยู่อาศัยหรือไม่?",answer:["ตราบใดที่คุณแจ้งให้เราทราบ 30 วันก่อนวันที่จะย้าย จะไม่มีค่าธรรมเนียม"]},{question:"นักเรียนคนใดจะได้รับอนุญาตให้เข้าร่วมชั้นเรียนแบบตัวต่อตัว",answer:["นักเรียนทุกคนที่เดินทางมาสหรัฐอเมริกาด้วย I-20 เบื้องต้น (นักเรียนใหม่) จะต้องเข้าร่วมโปรแกรมแบบตัวต่อตัวเนื่องจากข้อกำหนด SEVIS (การย้ายถิ่นฐานของสหรัฐอเมริกา) หากคุณเป็นนักศึกษาโอนย้ายที่มาสหรัฐอเมริกาก่อนวันที่ 3\u002F09\u002F20 คุณจะสามารถเลือกโปรแกรมออนไลน์หรือโปรแกรมตัวต่อตัวได้ นักเรียนใหม่ที่ไม่ใช่ F1 สามารถเลือกเรียนแบบตัวต่อตัวหรือแบบออนไลน์ได้"]},{question:"ฉันสามารถเข้าร่วมชั้นเรียนแบบตัวต่อตัวผ่าน Zoom ระหว่างการกักกันตัวเองได้หรือไม่",answer:["หากจำเป็นต้องกักกัน คุณอาจเข้าร่วมโปรแกรมออนไลน์ของเราได้ชั่วคราว: โปรแกรม TOEFL ภาคค่ำหรือโปรแกรม Conversation Advanced ภาคค่ำ"]}]},{title:"คำถามทั่วไปเกี่ยวกับ COVID-19",lists:[{question:"ฉันจะรับการทดสอบ COVID-19 ฟรีได้อย่างไร",answer:["หากคุณทำการสอบ PCR จากเขต LA การทดสอบนั้นฟรี โปรดเยี่ยมชมเว็บไซต์การทดสอบ COVID-19 ของเทศมณฑลแอลเอ: \u003Cbr \u002F\u003E \u003Ca href='https:\u002F\u002Fcovid19.lacounty.gov\u002Ftesting\u002F' target='_blank'\u003Ehttps:\u002F\u002Fcovid19.lacounty.gov\u002Ftesting\u002F\u003C\u002Fa\u003E"]},{question:"จะเกิดอะไรขึ้นถ้าฉันผลตรวจเป็นบวกสำหรับ COVID-19",answer:["อันดับแรก คุณต้องมีประกันสุขภาพ\u002Fการเดินทาง ซึ่งจะครอบคลุมประเด็นที่เกี่ยวข้องกับ COVID-19 หากคุณได้รับผลบวก ให้ทำตามคำแนะนำของศูนย์ทดสอบ LA"]},{question:"ฉันควรทำอย่างไรหากเชื่อว่าตนเองอาจติดเชื้อโควิด-19",answer:["คุณควรสอบ PCR L.A. Country จัดให้มีการสอบ PCR ฟรี สำหรับรายละเอียดเพิ่มเติม โปรดเยี่ยมชมเว็บไซต์ของเทศมณฑลแอลเอ: \u003Cbr \u002F\u003E \u003Ca href='https:\u002F\u002Fcovid19.lacounty.gov\u002Ftesting\u002F' target='_blank'\u003Ehttps:\u002F\u002Fcovid19.lacounty.gov\u002Ftesting\u002F\u003C\u002Fa\u003E"]},{question:"อาการของโรคโควิด-19 มีอะไรบ้าง?",answer:["สำหรับรายละเอียดเกี่ยวกับอาการของ COVID-19 โปรดดูเว็บไซต์ CDC (ศูนย์ควบคุมและป้องกันโรค): \u003Cbr \u002F\u003E \u003Ca href='https:\u002F\u002Fwww.cdc.gov\u002Fcoronavirus\u002F2019-ncov\u002Fsymptoms-testing\u002Fsymptoms.html' target='_blank'\u003Ehttps:\u002F\u002Fwww.cdc.gov\u002Fcoronavirus\u002F2019-ncov\u002Fsymptoms-testing\u002Fsymptoms.html. \u003C\u002Fa\u003E  \u003Cbr \u002F\u003E นอกจากนี้ยังมี Coronavirus Self-Checker อีกด้วย: \u003Cbr \u002F\u003E \u003Ca href='https:\u002F\u002Fwww.cdc.gov\u002Fcoronavirus\u002F2019-ncov\u002Fsymptoms-testing\u002Fcoronavirus-self-checker.html' target='_blank'\u003Ehttps:\u002F\u002Fwww.cdc.gov\u002Fcoronavirus\u002F2019-ncov\u002Fsymptoms-testing\u002Fcoronavirus-self-checker.html \u003C\u002Fa\u003E"]},{question:"สถานการณ์ COVID-19 ในแอลเอเป็นอย่างไร?",answer:["กรณีของ COVID-19 เพิ่มขึ้นเมื่อเร็ว ๆ นี้ในลอสแองเจลิสเคาน์ตี้เนื่องจากตัวแปร Omnicron เนื่องจากการแพร่เชื้อของ COVID-19 ในลอสแองเจลีสเคาน์ตี้สูงมากในขณะนี้ ผู้ไม่ได้รับวัคซีนจึงมีความเสี่ยงสูงมาก คนที่ได้รับวัคซีนมีความเสี่ยงต่ำกว่า สำหรับข้อมูล COVID-19 ของ LA County ดู: \u003Cbr \u002F\u003E \u003Ca href='http:\u002F\u002Fwww.publichealth.lacounty.gov\u002Fmedia\u002FCoronavirus\u002Fdata\u002F' target='_blank'\u003Ehttp:\u002F\u002Fwww.publichealth.lacounty.gov\u002Fmedia\u002FCoronavirus\u002Fdata\u002F \u003C\u002Fa\u003E"]}]}],dir:"\u002Ffaq-covid19",path:"\u002Ffaq-covid19\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:29.160Z",updatedAt:"2025-05-26T12:06:27.739Z"}}],fetch:{},mutations:void 0}}("ข้อบังคับการเดินทาง นโยบาย MLI COVID-19 และสถานะ COVID-19 ในลอสแองเจลิส")));